ui.heard.next.$fn:
(v) => {
    const mark = (r) => (r ? ' <b class="next-law-react">맞섬</b>' : '');
    return v.alt ? `율법파 「${v.name}」${mark(v.reacted)} 또는 「${v.alt.name}」${mark(v.alt.reacted)}` : `율법파 「${v.name}」${mark(v.reacted)}`;
  }

ui.chapter.sub.$fn:
(v) => {
    const act = v.last ? '최후의 계절 · ' : v.hasAct ? `${v.act} · ` : '';
    const fest = v.hasFest ? `${v.fest} · ` : '';
    return v.first ? `${act}${v.event}${v.judge != null ? ` · 심판의 기준 「${v.judge}」` : ''}` : `${fest}${act}${v.event}`;
  }

ui.verdict.text.$fn:
(v) => {
    const ira = `'${v.word}'${batchim(v.word) ? '이라' : '라'}`;
    if (v.grade === 'odd') return `신께서 ${ira} 하셨으나 사제는 다르게 들었다. 그래도 ${v.deed || '무언가 이루어졌다'}.`;
    return v.grade === 'miss' ? `신께서 ${ira} 하셨으나, 말씀은 아직 이루어지지 않았다.` : `신께서 ${ira} 하셨고, ${v.deed}.`;
  }

ui.season.swap.$fn:
(v) => {
    const last = v.raw.charCodeAt(v.raw.length - 1) - 0xac00;
    const ro = last >= 0 && last % 28 !== 0 && last % 28 !== 8 ? '으로' : '로';
    return `지혜의 눈 · 「${v.name}」${ro} 바꾸기`;
  }

log.legacy.$fn:
(v) => {
    const who = v.god ? `「${v.epithet}」 ${v.god}` : `「${v.epithet}」`;
    return `전생의 유적 — 여기 ${who}${ga(v.god || v.epithet)} “${v.quote}”라 말씀하셨다. ${v.doc ? `${v.doc} +1` : '신앙 +2'}.`;
  }

interp.lessonName.$fn:
(v) => {
    const type = { gather: '채집', pray: '기도', build: '건설', preach: '선교', attack: '공격', explore: '탐험' };
    return v.gather ? `${type.gather}(${{ food: '식량', wood: '목재', stone: '돌', faith: '신앙' }[v.gather]})`
      : v.build ? { village: '마을 건설', wall: '성벽', temple: '신전', cathedral: '대성당' }[v.build] : type[v.type];
  }

interp.prompt.$fn:
(v) => `[부족 상황]
자원: 식량 ${v.food}, 목재 ${v.wood}, 돌 ${v.stone}, 신앙 ${v.faith}
신도: ${v.pop}명 (이번 라운드 행동 가능 ${v.limit}회), 신전 ${v.templeLevel}단계, 마을 ${v.villages}개
율법파: 신도 ${v.enemyPop}명, 마을 ${v.enemyVillages}개, 수도 내구도 ${v.capitalHp}${v.threat ? `\n율법파의 의도: ${v.threat}` : ''}
지난 계시: ${v.recent}${v.god ? `\n너의 신의 이름은 ${v.god}이다.` : ''}${v.lessons ? `\n대사제가 깨달은 신의 말버릇: ${v.lessons}` : ''}${v.voice ? `\n${v.voice}` : ''}${v.canon != null ? `\n이 부족의 경전: "${v.canon}"` : ''}${v.priest ? `\n${v.priest}` : ''}

[가능한 행동]
${v.actions}

[최근 사건]
${v.event}${v.choice ? `\n이번 사건의 갈림길: ${v.choice}` : ''}${v.next ? `\n다음 장: ${v.next} 예고` : ''}

[신의 계시]
"${v.revelation}"

금지한 행동, 따를 행동(1~${v.limit}개), 교리를 정한 뒤, 고른 행동을 외치는 말을 JSON으로 답하라.`

interp.leaderLine.$fn:
(v) => {
    const w = v.word ?? '그 말';
    const b = batchim(w);
    return v.line.replaceAll("'{word}'라", `'${w}'${b ? '이라' : '라'}`).replaceAll("'{word}'를", `'${w}'${b ? '을' : '를'}`)
      .replaceAll("'{word}'?", `'${w}'?`).replaceAll('{word}', w);
  }
